// Consume only the Worker projection; membership levels are not interpreted here.
export function resolveVerifiedCustomerBrand(data, authority) {
  return authority === 'canonical_member_account_v1' && data?.brand_audience === 'sigil'
    ? 'private' : 'unresolved';
}
// Graphic-pack V6 display adapter. This module never reads tier, session, tokens or URL hints.
export function createCustomerBrand(root) {
  const panels = root?.querySelectorAll?.('[data-brand-panel]') || [];
  const failedAssets = new Set();
  let currentAudience = 'unresolved';
  function render(audience) {
    const resolved = (audience === 'public' || audience === 'private') && !failedAssets.has(audience)
      ? audience : 'unresolved';
    currentAudience = resolved;
    for (const panel of panels) {
      panel.hidden = panel.getAttribute('data-brand-panel') !== (resolved === 'unresolved' ? 'neutral' : resolved);
    }
    if (root?.dataset) root.dataset.audience = resolved;
    if (root?.ownerDocument?.body?.dataset) root.ownerDocument.body.dataset.brandAudience = resolved;
    return resolved;
  }
  for (const panel of panels) {
    const audience = panel.getAttribute('data-brand-panel');
    const image = panel.querySelector?.('img');
    if (image?.complete && image.naturalWidth === 0) failedAssets.add(audience);
    image?.addEventListener?.('error', () => {
      failedAssets.add(audience);
      // A late failure from a hidden audience must not clear the current header.
      if (currentAudience === audience) render(null);
    }, { once: true });
  }
  return { render, reset: () => render(null) };
}
